update public.fields set verification_status='verified_against_standard', verification_quote='This document gives general guidelines for organizations seeking to address water-related environmental aspects, environmental impacts, environmental conditions, and the associated risks and opportunities within an environmental management system in accordance with ISO 14001. | ISO 14001, Environmental management systems — Requirements with guidance for use — printed p.1 (PDF p.13)', verification_note='VA-verified 2026-09-08 (§1 Scope + §2 Normative references, printed p.1 (PDF p.13) — ISO 14001 is the ONLY normative reference of this document, so an ISO 14001 EMS is the framework the whole guidance presupposes; note the printed modality is "gives general guidelines", never "shall") [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='8a1c4fc2-8e90-4a0b-819e-4fee795cc3a3' and verification_status not in ('verified_against_standard','corrected');

