update public.fields set verification_status='verified_against_standard', verification_quote='Note 1 to entry: An environmental aspect can cause (an) environmental impact(s) (3.4). A significant environmental aspect is one that has or can have one or more significant environmental impact(s). | Note 2 to entry: Significant environmental aspects are determined by the organization applying one or more criteria. | identify those that that are significant and that it will address in its environmental management system. — printed pp.2, 4 (PDF pp.14, 16)', verification_note='VA-verified 2026-09-08 (§3.2 Notes 1 and 2, printed p.2 (PDF p.14) + §4.2.2, printed p.4 (PDF p.16) — the standard leaves the significance CRITERIA to the organization ("applying one or more criteria"), so no threshold is encodable and none is encoded; the doubled "that that" is the genuine printed typo, confirmed on the rendered page) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='469b264f-adca-4e91-b5ff-46f4e17faaae' and verification_status not in ('verified_against_standard','corrected');

