update public.fields set verification_status='verified_against_standard', verification_quote='Information related to water inputs and outputs can include: — current water sources (e.g. water bodies, precipitation, groundwater); — current water uses (e.g. drinking, cleaning, cooling water, irrigation, industrial process, ingredient of products), water quality and quantity; — current water reuse, recycling and recirculation; — current water discharges; — potential conflicts of water users. — printed p.4 (PDF p.16)', verification_note='VA-verified 2026-09-08 (§4.2.2, printed p.4 (PDF p.16) — the five enum values map 1:1 onto the five printed bullets; CAVEAT: the printed lead-in is "can include", i.e. an OPEN list, and the enum closes it with no "other" value — STAGED) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='9fda22fc-6f6f-4230-90c5-39bd11b79b7b' and verification_status not in ('verified_against_standard','corrected');

