update public.fields set verification_status='verified_against_standard', verification_quote='An organization should consider the potential effects originating from the dependency on and vulnerability to water. This can include considerations of: — nearby water sources the organization relies on and that are impacted by other organizations using the same water source, or by environmental conditions; — the impact of activities along the supply chain on water resources, if relevant; — the impact of water consumption and water pollution on the environment including aquatic and terrestrial ecosystems, and local communities. — printed p.5 (PDF p.17)', verification_note='VA-verified 2026-09-08 (§4.2.2, printed p.5 (PDF p.17) — Annex D (informative, PDF p.55) defines the printed verb: "The word ''consider'' means it is necessary to think about the topic but it can be excluded", which is weaker than the is_required=true this field carries — an is_required review is STAGED) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='1523510c-247e-4793-9c16-559b5e1ea03a' and verification_status not in ('verified_against_standard','corrected');

