-- risks_opportunities_determined
update public.fields set verification_status='verified_against_standard', verification_quote='Taking into consideration the issues identified as part of the context of the organization (see 4.2), including water-related environmental conditions, dependencies on water, as well as compliance obligations, the identified environmental aspects and impacts (see 4.2.2), and the effectiveness of existing control measures, an organization should determine the water-related risks and opportunities and prioritize those to be addressed to achieve the intended outcomes and policy commitments of its environmental management system. — printed p.5 (PDF p.17)', verification_note='VA-verified 2026-09-08 (§4.2.3 Determine risks and opportunities that need to be addressed, printed p.5 (PDF p.17)) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='b33db3b4-ba99-42de-a525-fb483598e201' and verification_status not in ('verified_against_standard','corrected');

