update public.fields set verification_status='verified_against_standard', verification_quote='Baseline references can be absolute or can be normalized using variables that affect water use, water consumption or water quality (see also 6.2.2). A baseline reference can be adjusted if needed, for example, following major changes to an organization’s processes, operations, facilities, or equipment that affect water use or consumption, or major changes in environmental conditions (see 4.2.5). — printed p.6 (PDF p.18)', verification_note='VA-verified 2026-09-08 (§4.2.4, printed p.6 (PDF p.18) — the two enum values (absolute / normalized) are exactly the printed alternatives; the printed list is closed ("can be absolute or can be normalized"), so closing the enum is correct here) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='c34661ef-c4dd-4d42-a198-4a1d8f55a3ae' and verification_status not in ('verified_against_standard','corrected');

-- change_management_reviewed
update public.fields set verification_status='verified_against_standard', verification_quote='The evaluation of risks and opportunities should be reviewed and updated routinely to ensure the environmental management system can achieve intended outcomes, especially following changes in the context of the organization, major changes to its processes, or modification and refurbishments to its facilities or equipment. — printed p.6 (PDF p.18)', verification_note='VA-verified 2026-09-08 (§4.2.5 Manage change, printed p.6 (PDF p.18) — the printed interval is "routinely"; the standard fixes NO period, so no interval value is encodable and none is encoded) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='a5cb5455-e76c-44e7-b776-c904f034646d' and verification_status not in ('verified_against_standard','corrected');

-- ============================ ISO-14002-2-05  Bestimmung & Planung von Maßnahmen ============================

-- appropriate_actions_determined
update public.fields set verification_status='verified_against_standard', verification_quote='When determining appropriate actions to address the identified water-related environmental aspects and environmental impacts, environmental conditions, dependencies on water, and the associated risks and opportunities (see 4.2), an organization can find it helpful to consider a range of options/actions within its environmental management system, in order to optimize its strategy for water management and minimize potential residual adverse effects. | An organization should plan actions based on the risks and opportunities and what needs to be addressed, considering the outputs from Clause 4. — printed pp.7, 9 (PDF pp.20, 22)', verification_note='VA-verified 2026-09-08 (§4.3 printed p.7 (PDF p.20) + §5.1 General printed p.9 (PDF p.22) — §4.3 is "can find it helpful" (weakest modality); the obligation rests on the §5.1 "should plan actions" sentence) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='7eb5f61d-4120-4263-ab21-ce0257cc7d65' and verification_status not in ('verified_against_standard','corrected');

-- action_type
update public.fields set verification_status='verified_against_standard', verification_quote='Actions can be applied singularly, or in combination, and can include setting environmental objectives, as well as implementing operational controls, support actions related to internal interested parties, or performance evaluation mechanisms. | Subclauses 5.2 to 5.5 provide guidance on types of action that can be taken. — printed pp.7, 9 (PDF pp.20, 22)', verification_note='VA-verified 2026-09-08 (§4.3 printed p.7 (PDF p.20) + §5.1 printed p.9 (PDF p.22) — the four enum values map onto the four printed action kinds and onto §§5.2-5.5; CAVEAT 1: the printed lead-in is "can include", an OPEN list (STAGED); CAVEAT 2: the printed text says actions "can be applied singularly, OR IN COMBINATION" while the field is a single-select enum — a multi-select review is STAGED) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='ded35312-dcaa-4ea8-81e6-7031d35de8eb' and verification_status not in ('verified_against_standard','corrected');

-- environmental_objective_set
update public.fields set verification_status='verified_against_standard', verification_quote='An organization should establish specific and relevant environmental objectives that are consistent with its environmental policy commitments and the identified significant environmental aspects and risks and opportunities related to sustainable use and protection of water resources. — printed p.11 (PDF p.24)', verification_note='VA-verified 2026-09-08 (§5.2 Environmental objectives, printed p.11 (PDF p.24)) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='b1412e8d-4bc8-41dc-8472-a15703c0de39' and verification_status not in ('verified_against_standard','corrected');

-- objective_level
update public.fields set verification_status='verified_against_standard', verification_quote='Environmental objectives can be strategic, tactical or operational. Objectives can be achieved via direct and indirect influence (see the example in Annex A). — printed p.11 (PDF p.24)', verification_note='VA-verified 2026-09-08 (§5.2, printed p.11 (PDF p.24) — the three enum values are exactly the three printed levels; the printed list is closed, so closing the enum is correct. Figure 3 on the same page carries the same three) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='3015442a-ad78-4f65-a3e7-675551935918' and verification_status not in ('verified_against_standard','corrected');

-- target_measurable_timebound
update public.fields set verification_status='verified_against_standard', verification_quote='The environmental objectives should also be achievable and include related targets that are measurable and time-bound. — printed p.11 (PDF p.24)', verification_note='VA-verified 2026-09-08 (§5.2, printed p.11 (PDF p.24) — the standard names NO measurement unit, horizon or tolerance, so nothing numeric is encodable and nothing numeric is encoded) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='838c9834-6ae6-4c04-bb0e-a95f3c8d7a9d' and verification_status not in ('verified_against_standard','corrected');

-- target_type
update public.fields set verification_status='verified_against_standard', verification_quote='Targets related to the environmental objectives can be qualitative or quantitative, and can involve absolute or relative targets or measures of performance. An absolute target is not normalized or measured in relation to the activity, and can be expressed as a desired level, number or state to be achieved. — printed p.11 (PDF p.24)', verification_note='VA-verified 2026-09-08 (§5.2, printed p.11 (PDF p.24) — CAVEAT: the printed sentence gives TWO ORTHOGONAL axes (qualitative|quantitative AND absolute|relative), joined by "and can involve"; the encoding flattens both into ONE 4-value single-select, so a target that is both quantitative and absolute cannot be recorded. A split into two fields is STAGED) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='50e19d65-5c1c-4728-99f2-304d1352657b' and verification_status not in ('verified_against_standard','corrected');

-- ============================ ISO-14002-2-06  Unterstützung & operative Steuerung ============================

-- support_actions_provided
update public.fields set verification_status='verified_against_standard', verification_quote='The organization should provide the necessary support in a manner that the organization can achieve its intended outcomes for the environmental management system. This can include the following: [...] Providing adequate resources to support the implementation of its environmental management system and for carrying out actions to achieve the organization’s environmental objectives related to water use and protection. — printed p.12 (PDF p.25)', verification_note='VA-verified 2026-09-08 (§5.3 Support actions, printed p.12 (PDF p.25) — the five printed support kinds (resources, competence, awareness, communication, documented information) are encoded as five separate booleans on this worksheet) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='b135ccd4-0214-45b5-a4fe-8dc011b2cca8' and verification_status not in ('verified_against_standard','corrected');

-- competence_determined
update public.fields set verification_status='verified_against_standard', verification_quote='Determining, developing and maintaining the competence of persons doing work under the organization’s control to have adequate knowledge, skills and qualifications in order to carry out work in accordance with the organization’s environmental objectives. — printed p.12 (PDF p.25)', verification_note='VA-verified 2026-09-08 (§5.3, second bullet, printed p.12 (PDF p.25); "person(s) doing work under the organization''s control" is clarified in Annex D (informative) as including contractors) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='f5d4756a-b86f-48fb-b3e8-f49169185d16' and verification_status not in ('verified_against_standard','corrected');

-- awareness_ensured
update public.fields set verification_status='verified_against_standard', verification_quote='Ensuring that persons doing work under the organization’s control have an awareness of how their work can affect water use, water consumption or water quality, ecosystems, related environmental objectives, impacts of deviating from operational controls, and their role in achieving the organization’s environmental objectives. — printed p.12 (PDF p.25)', verification_note='VA-verified 2026-09-08 (§5.3, third bullet, printed p.12 (PDF p.25); Annex D (informative) defines the printed verb: "The word ''ensure'' means the responsibility can be delegated, but not the accountability") [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='a51010fa-5be4-4f72-82c5-c10d9ea42712' and verification_status not in ('verified_against_standard','corrected');

-- documented_information_controlled
update public.fields set verification_status='verified_against_standard', verification_quote='Establishing and controlling water-related documented information to ensure that processes and actions are controlled and conducted as intended, and that the intended outcomes are achieved. — printed p.12 (PDF p.25)', verification_note='VA-verified 2026-09-08 (§5.3, fifth bullet, printed p.12 (PDF p.25) — the standard prescribes no document list, retention period or format for this information) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='d41d8f7c-fce5-483d-9ed6-10c9a3382563' and verification_status not in ('verified_against_standard','corrected');

-- operational_controls_applied
update public.fields set verification_status='verified_against_standard', verification_quote='To reduce variability, achieve intended outcomes and enhance performance with regard to sustainable use and protection of water resources, including ecosystems, an organization should apply relevant operational control(s) on the organization’s activities. — printed p.12 (PDF p.25)', verification_note='VA-verified 2026-09-08 (§5.4.1 General, printed p.12 (PDF p.25)) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='3994a1e1-b18d-4e3d-be40-b4a14fd3dcd6' and verification_status not in ('verified_against_standard','corrected');

-- control_hierarchy_type
update public.fields set verification_status='verified_against_standard', verification_quote='the organization can consider a hierarchy of control approach to minimize its actual and potential adverse impacts its water use and discharge has on the environment, including water resources and ecosystems, and to minimize actual and potential adverse effects from dependencies on water. | These types of pollution prevention approaches and types of control are described as follows: [...] Elimination: elimination of products, operations or environmental aspects of operations that pose a threat to the environment [...] Substitution: substitution with a less harmful process [...] Engineering: engineering controls target implementation of operations [...] Administrative: administrative controls include plans, rules, procedures, instructions, training and inspections — printed pp.12, 13 (PDF pp.25, 27)', verification_note='VA-verified 2026-09-08 (§5.4.2 Types of control, printed pp.12, 13 (PDF pp.25, 27) — the four enum values are exactly the four printed control types and the printed list IS closed ("described as follows"); CAVEAT: the modality is "can consider", the weakest in the document, yet gate CR-020 demands this optional (is_required=false) field be filled — a gate review is STAGED) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='8fefb242-591f-487e-a428-dd7811f5c918' and verification_status not in ('verified_against_standard','corrected');

-- lifecycle_controls_applied
update public.fields set verification_status='verified_against_standard', verification_quote='In addition to applying operational controls over the organization’s activities, operational controls can also be applied with regard to a life cycle perspective if relevant. To take a life cycle perspective in managing the use and protection of water resources, an organization should consider the relevant stages of the life cycle of products that use or discharge water, or that otherwise have or can have an impact on water resources. — printed p.13 (PDF p.27)', verification_note='VA-verified 2026-09-08 (§5.4.3 Life cycle perspective, printed p.13 (PDF p.27) — printed "can also be applied ... if relevant", which matches the encoded is_required=false) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='080a4e77-1a4f-4eb6-b81a-1a0b3dd215f0' and verification_status not in ('verified_against_standard','corrected');

-- emergency_preparedness_planned
update public.fields set verification_status='verified_against_standard', verification_quote='Organizations should plan for emergency situations by: — identifying the potential water-related emergency situations that can have an effect on the organization and its activities, or adverse impacts on the environment; — determining risks and opportunities associated with water-related emergency situations as part of its planning process (see 4.2); — identifying uses of water that can be affected by the water emergencies; — printed p.14 (PDF p.28)', verification_note='VA-verified 2026-09-08 (§5.4.4 Emergency preparedness and response, printed p.14 (PDF p.28) — the encoded description lists exactly the printed five-step sequence) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='e9caf67d-291c-49cc-ad0a-632be5c45bad' and verification_status not in ('verified_against_standard','corrected');

-- emergency_situation_type
update public.fields set verification_status='verified_against_standard', verification_quote='Emergency preparedness and response with regard to water-related environmental conditions such as floods, drought, supply and discharge disruptions, and impacts on water quality such as spills and contaminations are also part of good operational control. — printed p.14 (PDF p.28)', verification_note='VA-verified 2026-09-08 (§5.4.4, printed p.14 (PDF p.28) — the four enum values map 1:1 onto the four printed situations; CAVEAT: the printed lead-in is "such as", i.e. an OPEN list, and the enum closes it with no "other" value, while the same clause also names extreme weather and climate-change effects — STAGED) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='8e2eadb0-a2a0-4240-b26b-37c48c84ee0e' and verification_status not in ('verified_against_standard','corrected');

-- emergency_response_tested
update public.fields set verification_status='verified_against_standard', verification_quote='Organizations should plan for emergency situations by: [...] where appropriate, establishing a response plan(s) or procedure(s) for addressing the identified actual and potential adverse effects (threats) and reducing the impact of water-related emergencies [...] at planned intervals, testing and reviewing the effectiveness of the emergency response plan(s) and procedure(s). — printed p.14 (PDF p.28)', verification_note='VA-verified 2026-09-08 (§5.4.4, fourth and fifth bullets, printed p.14 (PDF p.28) — the printed interval is "at planned intervals"; the standard fixes NO period, so no interval value is encodable and none is encoded) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='4fa26f77-6357-4874-9841-b4d057b510a0' and verification_status not in ('verified_against_standard','corrected');

-- ============================ ISO-14002-2-07  Leistung, Folgen & Überwachung ============================

-- performance_action_type
update public.fields set verification_status='verified_against_standard', verification_quote='An organization can plan performance-related actions to address significant environmental aspects and risks and opportunities. Performance action can include, for example: — monitoring and measurement relative to specific indicators, parameters or characteristics; — observations or inspections to ensure awareness of current conditions and allow for intervention if needed; — analysis, evaluation or auditing to identify water-related trends. — printed p.15 (PDF p.29)', verification_note='VA-verified 2026-09-08 (§5.5 Performance action, printed p.15 (PDF p.29) — the three enum values map 1:1 onto the three printed bullets; CAVEAT: the printed lead-in is "can include, for example", an OPEN list closed by the enum (STAGED). Note also that §5.5 contains NO "should" at all — it is pure "can" — so no gate rests on this field, and correctly none does) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='806f1ec4-f710-4875-8971-f71f532325f6' and verification_status not in ('verified_against_standard','corrected');

-- effectiveness_evaluated
update public.fields set verification_status='verified_against_standard', verification_quote='An organization should evaluate if and to what extent the actions taken related to water withdrawal, water use and water quality as well as the use of aquatic ecosystems are effective. This can include evaluating effectiveness in the following areas: — improving environmental performance and achieving environmental objectives; — fulfilling compliance obligations; — addressing identified water-related risks and opportunities. — printed p.16 (PDF p.30)', verification_note='VA-verified 2026-09-08 (§6.1 General, printed p.16 (PDF p.30)) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='40f7e8df-ffb0-4b2d-8f9c-d70bccc8c347' and verification_status not in ('verified_against_standard','corrected');

-- monitoring_measurement_defined
update public.fields set verification_status='verified_against_standard', verification_quote='An organization should decide on what needs to be monitored or measured, and when, who carries out the monitoring activities, which methods are applied, what data quality is necessary and how the data are to be analysed to support the evaluation. Monitoring, measurement and analysis should take into account feedback from interested parties, including the information needs and expectations of intended users (e.g. operational management, strategic management, and other internal and external interested parties). — printed p.16 (PDF p.30)', verification_note='VA-verified 2026-09-08 (§6.2.1 General, printed p.16 (PDF p.30) — Annex D (informative) distinguishes the two printed verbs: "take into account" means the topic "cannot be excluded", unlike "consider") [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='f2dc0543-9361-4344-84a2-79d733e79ae6' and verification_status not in ('verified_against_standard','corrected');

-- data_quality_defined
update public.fields set verification_status='verified_against_standard', verification_quote='An organization should decide on what needs to be monitored or measured, and when, who carries out the monitoring activities, which methods are applied, what data quality is necessary and how the data are to be analysed to support the evaluation. — printed p.16 (PDF p.30)', verification_note='VA-verified 2026-09-08 (§6.2.1, printed p.16 (PDF p.30) — the field isolates the "what data quality is necessary" limb of the printed sentence; the standard defines NO data-quality classes, tiers or acceptance criteria, so nothing beyond a free attestation is encodable) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='ef49322e-8a40-4313-a37f-2df4f0ccefdb' and verification_status not in ('verified_against_standard','corrected');

-- unintended_consequences_reviewed
update public.fields set verification_status='verified_against_standard', verification_quote='An organization should be aware that actions can have unplanned reactions or unintended consequences. All actions taken should be reviewed in a timely manner with regard to resulting changes in uses of water, environmental impacts associated with water or other environmental media, and any foreseeable emergency situations. These unintended consequences can also be delayed, e.g. with respect to groundwater. — printed p.15 (PDF p.29)', verification_note='VA-verified 2026-09-08 (§5.6 Unintended consequences of actions taken, printed p.15 (PDF p.29) — the printed deadline is "in a timely manner"; no period is fixed by the standard) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='eb253172-82a4-4ba5-9725-4b359d5175b7' and verification_status not in ('verified_against_standard','corrected');

-- ============================ ISO-14002-2-08  Indikatoren, Bewertung & Verbesserung ============================

-- performance_indicators_tracked
update public.fields set verification_status='verified_against_standard', verification_quote='To enable this comparison, an organization should identify and track progress against relevant, fundamental indicators of performance, or key performance indicators (KPIs). | KPIs should be selected to allow for comparison of performance over time, in relation to the established environmental objectives and related targets. Baseline performance can be used as a reference point for this comparison. — printed p.17 (PDF p.32)', verification_note='VA-verified 2026-09-08 (§6.2.2 Indicators of performance, printed p.17 (PDF p.32)) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='971b835b-f2ea-41f9-925c-c30f7359c231' and verification_status not in ('verified_against_standard','corrected');

-- indicator_type
update public.fields set verification_status='verified_against_standard', verification_quote='leading indicator metric that gives an indication of expected performance | lagging indicator metric that gives an indication of past performance | A comprehensive set of lagging and leading indicators can be useful for evaluating performance at operational as well as strategic levels of management — printed pp.3, 17 (PDF pp.15, 32)', verification_note='VA-verified 2026-09-08 (§3.10 and §3.11, printed p.3 (PDF p.15), both [SOURCE: ISO 10014:2021] + §6.2.2, printed p.17 (PDF p.32) — the two enum values are exactly the two printed defined terms) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='25b44e31-f51c-4165-8346-a38f71ee8d29' and verification_status not in ('verified_against_standard','corrected');

-- kpi_measurement_type
update public.fields set verification_status='verified_against_standard', verification_quote='KPIs can involve simple or complex measurements, for example: — simple, absolute measures of the characteristics of environmental aspects, environmental conditions or relevant management processes, independent of other factors; — relative measurements that express or normalize one factor in relation to another; — composite measurements in the form of an index or scale that incorporates multiple factors. — printed p.17 (PDF p.32)', verification_note='VA-verified 2026-09-08 (§6.2.2, printed p.17 (PDF p.32) — the three enum values map 1:1 onto the three printed bullets; CAVEAT: the printed lead-in is "for example", an OPEN list closed by the enum — STAGED) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='ee514d8e-d867-4f0f-8f1d-3bad963f5751' and verification_status not in ('verified_against_standard','corrected');

-- improvement_actions_implemented
update public.fields set verification_status='verified_against_standard', verification_quote='Based on the evaluation results (see Clause 6), an organization should address gaps in the effectiveness of the actions taken, and any identified nonconformities, including their causes, requiring corrections and corrective actions. It should determine opportunities for improvement and implement the necessary actions to achieve its water-related intended outcomes. — printed p.18 (PDF p.33)', verification_note='VA-verified 2026-09-08 (§7 Improvement, printed p.18 (PDF p.33)) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='5d84a8c4-992f-48d5-acc7-d811bd5ea51a' and verification_status not in ('verified_against_standard','corrected');

-- nonconformities_addressed
update public.fields set verification_status='verified_against_standard', verification_quote='an organization should address gaps in the effectiveness of the actions taken, and any identified nonconformities, including their causes, requiring corrections and corrective actions. | Opportunities for improvement are not necessarily limited to the management of water, and can also be related to environmental impacts on soil, air, biodiversity and other resources. — printed p.18 (PDF p.33)', verification_note='VA-verified 2026-09-08 (§7 Improvement, printed p.18 (PDF p.33) — this field isolates the nonconformity limb of the same printed sentence that carries improvement_actions_implemented; the standard defines no nonconformity classes or closure deadlines) [VA · ISO 14002-2:2023 published First edition 2023-05, PDF text layer]', verified_at=now() where id='8799b01c-c7ce-4eb6-8f6a-20e683a2dbef' and verification_status not in ('verified_against_standard','corrected');

-- ============================ APP / PROJECT METADATA (exempt, 2026-08-01 ruling) ============================
-- 2 fields.  ISO 14002-2:2023 never defines, requires or formats either of these: the standard's
-- own identifier is a property of the library, and the organization's NAME appears nowhere as a
-- data item (Clause 1 speaks of "organizations" generically; the named organizations in the text -
-- Salmo Papers, Ames Community Water system, Pavitra Dairy Ltd., AB Chemical - are all INFORMATIVE
-- worked examples in Tables 1-8 and Annexes A-C).  No quote is fabricated for them.
update public.fields set verification_status='inferred_from_worksheet', verification_note='VA-pass 2026-09-08: app/project metadata — the guideline does not define this field; exempt per the 2026-08-01 metadata ruling. ISO 14002-2:2023 carries no field, table or clause that names or formats the standard code or the applying organization''s name; the organizations named in the document (Salmo Papers, Ames Community Water system, Pavitra Dairy Ltd., AB Chemical) are informative worked examples only', verified_at=now() where id in ('3299869c-edba-48d8-8ed3-bce1636f327f','f1e2bba2-435d-4012-818e-fe46b972ba69') and verification_status not in ('verified_against_standard','corrected');
